class Solution:
    def firstCrossIndex(self, N: int, P: int) -> int:
        is_prime = bytearray([1]) * (N + 1)
        is_prime[0] = 0
        if N >= 1:
            is_prime[1] = 0
        for i in range(2, int(N ** 0.5) + 1):
            if is_prime[i]:
                is_prime[i * i::i] = bytearray(len(range(i * i, N + 1, i)))
        primes = [i for i in range(2, N + 1) if is_prime[i]]
        total = sum(primes)
        # every full lap adds total, so only the remainder matters
        remainder = P % total
        running = 0
        for index, p in enumerate(primes):
            running += p
            if running > remainder:
                return index
        return -1

